import { MakeLogicType, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { getCurrentTeamId } from 'lib/utils/getAppContext'

import {
    errorTrackingSettingsRetrieveSettingsRetrieve,
    errorTrackingSettingsUpdateSettingsPartialUpdate,
} from '../../../generated/api'
import type { ErrorTrackingSettingsApi } from '../../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface exceptionIngestionLogicValues {
    ingestionEnabled: boolean | null
    settings: ErrorTrackingSettingsApi | null
    settingsLoadFailed: boolean
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface exceptionIngestionLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: any
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: any
    }
    setIngestionEnabled: (ingestionEnabled: boolean) => boolean
    setIngestionEnabledFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    setIngestionEnabledSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: boolean
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface exceptionIngestionLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        ingestionEnabled: (settings: ErrorTrackingSettingsApi | null) => boolean | null
    }
}

export type exceptionIngestionLogicType = MakeLogicType<
    exceptionIngestionLogicValues,
    exceptionIngestionLogicActions,
    Record<string, any>,
    exceptionIngestionLogicMeta
>

export const exceptionIngestionLogic = kea<exceptionIngestionLogicType>([
    path([
        'products',
        'error_tracking',
        'scenes',
        'ErrorTrackingConfigurationScene',
        'general',
        'exceptionIngestionLogic',
    ]),

    loaders({
        settings: [
            null as ErrorTrackingSettingsApi | null,
            {
                loadSettings: async () => {
                    return await errorTrackingSettingsRetrieveSettingsRetrieve(getCurrentTeamId().toString())
                },
                setIngestionEnabled: async (ingestionEnabled: boolean) => {
                    return await errorTrackingSettingsUpdateSettingsPartialUpdate(getCurrentTeamId().toString(), {
                        ingestion_enabled: ingestionEnabled,
                    })
                },
            },
        ],
    }),

    reducers({
        settingsLoadFailed: [
            false,
            {
                loadSettings: () => false,
                loadSettingsFailure: () => true,
            },
        ],
    }),

    selectors({
        ingestionEnabled: [
            (s) => [s.settings],
            (settings: ErrorTrackingSettingsApi | null): boolean | null =>
                settings ? settings.ingestion_enabled !== false : null,
        ],
    }),

    listeners({
        setIngestionEnabledSuccess: ({ settings }) => {
            const ingestionEnabled = settings.ingestion_enabled !== false
            // pinned: analytics event name, renaming it breaks dashboards
            posthog.capture('error_tracking_ingestion_toggled', { ingestion_enabled: ingestionEnabled })
            lemonToast.success(ingestionEnabled ? 'Exception ingestion turned on' : 'Exception ingestion turned off')
        },
    }),

    afterMount(({ actions }) => {
        actions.loadSettings()
    }),
])
